const YOUR_ORCID="0000-0002-5640-4413",API_BACKEND_URL="https://s.aintlab.com",YOUR_GS_ID="WLTzkOMAAAAJ",elements={yearofexp:document.getElementById("yearofexp"),footerInfo:document.getElementById("additionalInfo"),workCountText:document.getElementById("workCountText"),citedCount:document.getElementById("citedCount"),outletCount:document.getElementById("outletCount"),recentUpdates:document.getElementById("recentUpdates")},d=new Date,curryear=d.getFullYear(),yearofexp=curryear-2014,fetchWorks=(elements.yearofexp.innerHTML=yearofexp,async()=>{try{var e=(await axios.get(`${API_BACKEND_URL}/authorid/${YOUR_GS_ID}.json`)).data;return e&&(elements.workCountText.innerHTML=e.total_papers,elements.citedCount.innerHTML=e.total_citations,elements.footerInfo.innerHTML=`<p class="italic">(*) Publications and citations from <a href="${e.gs_id}&view_op=list_works&sortby=pubdate" target="_blank" class="link">Google Scholar</a>, (**) reviews from <a href="https://orcid.org/0000-0002-5640-4413" target="_blank" class="link">ORCID</a>. Updated ${e.updated}.</p>`),e}catch(e){}}),fetchReviews=async()=>{try{var e=(await axios.get(`${API_BACKEND_URL}/orcid/${YOUR_ORCID}/reviews.json`)).data;return e&&(elements.outletCount.innerHTML=e.total_outlets),e}catch(e){}},fetchUpdates=async()=>{try{var e=(await axios.get("https://aintlab.com/updates/rss.xml")).data;const a=fromXML(e),n=a.rss.channel.item.slice(0,4);var t=n.map(e=>`<a href='${e.link}' target='_blank' class='link' data-tippy-content='View this update'>${e.title}</a>`).join(", ");t+=", <a href='https://aintlab.com/updates' class='link' data-tippy-content='View all updates' target='_blank'>All updates</a>",elements.recentUpdates.innerHTML=t}catch(e){}},init=async()=>{await Promise.all([fetchWorks(),fetchReviews(),fetchUpdates()])},yearbuild=(init(),document.getElementById("yearbuild")),toggle=(yearbuild.innerHTML=(new Date).getFullYear(),tippy(".link",{placement:"bottom"}),document.querySelector(".js-change-theme")),root=document.docume